import math

def phi(z):
    # standard normal cdf
    return 0.5 * (1 + math.erf(z / math.sqrt(2)))

def p_value(z, two_sided=True):
    if two_sided:
        return 2 * (1 - phi(abs(z)))
    return 1 - phi(z)  # H1: mu > mu0
